func captureSpawns(t *testing.T) (*string, *[]string, *int) {
	t.Helper()
	original := spawnDetached
	t.Cleanup(func() { spawnDetached = original })
	var dir string
	var args []string
	spawned := 0
	spawnDetached = func(d string, a ...string) {
		dir = d
		args = slices.Clone(a)
		spawned++
	}
	return &dir, &args, &spawned
}

